Syllabus / Topics / Notes: {{ $json.topics || $json.notes || $json.query || $json.chatInput || 'Python Fundamentals: Control structures, functions, recursion, and time complexity' }}

Formatting Requirement for Flashcards:
At the end of your response, list at least 10 flashcards using this exact one-line format per card so the script can export them to CSV:
FLASHCARD: [Question or Front] || [Answer or Back]

parameters.jsCode:
const trigger = $('When Executed by Another Workflow').first().json;
const rawTaskId = trigger.task_id || new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-study';
const llmOutput = $input.first().json.text || $input.first().json.output || '';

const lines = llmOutput.split('\n');
const csvRows = ['"Front","Back"'];

for (const line of lines) {
  if (line.trim().startsWith('FLASHCARD:')) {
    const content = line.replace(/^FLASHCARD:\s*/i, '').trim();
    const parts = content.split('||');
    if (parts.length >= 2) {
      const front = parts[0].trim().replace(/"/g, '""');
      const back = parts.slice(1).join(' ').trim().replace(/"/g, '""');
      csvRows.push(`"${front}","${back}"`);
    }
  }
}

return [
  {
    json: {
      task_id: rawTaskId,
      study_guide_filename: `${rawTaskId}-study-guide.md`,
      study_guide_markdown: llmOutput,
      flashcards_csv_filename: `${rawTaskId}-flashcards.csv`,
      flashcards_csv_content: csvRows.join('\n'),
      flashcard_count: csvRows.length - 1
    }
  }
];
